def evolve(state: str, offsets: list[int], t: int) -> str:
    n = len(state)
    bits = int(state[::-1], 2)
    mask = (1 << n) - 1

    shifts = set()
    for offset in offsets:
        shift = offset % n
        if shift in shifts:
            shifts.remove(shift)
        else:
            shifts.add(shift)

    while t:
        if t & 1:
            result = 0
            for shift in shifts:
                if shift:
                    result ^= (bits >> shift) | ((bits << (n - shift)) & mask)
                else:
                    result ^= bits
            bits = result

        t >>= 1
        if t:
            next_shifts = set()
            for shift in shifts:
                doubled = (shift * 2) % n
                if doubled in next_shifts:
                    next_shifts.remove(doubled)
                else:
                    next_shifts.add(doubled)
            shifts = next_shifts

    return format(bits, f"0{n}b")[::-1]
